// Kronos Bot — Nodo Function: parsear callback_query de los botones
// Fase A (solo botones, sin EA/MT4 todavía)
const callbackQuery = $input.first().json.callback_query;
const [action, signalIdRaw] = (callbackQuery.data || '').split(':');
return [{
  json: {
    action, // 'confirm' o 'reject'
    signalId: parseInt(signalIdRaw, 10),
    callbackQueryId: callbackQuery.id,
  },
}];

// Kronos Bot — Etapa 4 (puente MT4): arma el JSON de orden pendiente
// según el contrato exacto de mt4-bridge/FORMATO_ARCHIVOS.md.
// Lotaje dinámico (PROTOCOLOS_KRONOS_BOT.md sección 5.2): floor(capital_real / 100) * 0.01,
// con piso de 0.01 si el cálculo da 0 o negativo. NO es el cálculo de slots 80/20 de la
// sección 5.3 (ese sigue sin implementar) — acá no hay competencia entre sub-señales.
const row = $('Obtener señal confirmada').item.json;
const capitalRow = $input.first().json;
const capitalReal = Number(capitalRow.capital_real);

let lot = Math.floor(capitalReal / 100) * 0.01;
if (!(lot > 0)) {
  lot = 0.01;
}
lot = Number(lot.toFixed(2));

const order = {
  signal_id: row.id,
  signal_uid: row.signal_uid,
  instrument: row.instrument,
  direction: row.direction,
  execution_type: row.execution_type,
  entry_price: Number(row.entry_price),
  sl: Number(row.sl),
  tp: Number(row.tp),
  lot,
  created_at: new Date().toISOString(),
};

const buffer = Buffer.from(JSON.stringify(order, null, 2), 'utf-8');
const binary = await this.helpers.prepareBinaryData(buffer, `${row.id}.json`, 'application/json');

return [{
  json: order,
  binary: { data: binary },
}];

// Kronos Bot — Etapa 5 (puente MT4): parsea cada resultado leído de
// mt4-bridge/orders/results/{signal_id}.json (formato en
// mt4-bridge/FORMATO_ARCHIVOS.md sección 2).
// El nodo 'Leer resultados (MT4)' guarda el binario en modo
// filesystem-v2 (no viene en base64 dentro de item.binary.data.data),
// por eso se usa this.helpers.getBinaryDataBuffer para leer el
// contenido real del archivo.
const results = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const binaryMeta = item.binary.data;
  const fullPath = `${binaryMeta.directory}/${binaryMeta.fileName}`;
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  const parsed = JSON.parse(buffer.toString('utf-8'));

  results.push({
    json: {
      signal_id: parsed.signal_id,
      success: parsed.success,
      ticket: parsed.ticket,
      executed_price: parsed.executed_price,
      error_code: parsed.error_code,
      error_message: parsed.error_message,
      fileName: fullPath,
    },
  });
}

return results;

// Kronos Bot — Etapa 5 (puente MT4): borra el archivo de
// mt4-bridge/orders/results/{signal_id}.json ya procesado.
// Se ejecuta siempre (haya notificado o no), igual que el EA nunca
// reprocesa pending/. fileName se recupera del nodo 'Parsear
// resultado (MT4)' porque el nodo Postgres intermedio reemplaza
// item.json por las columnas devueltas por la query.
const fs = require('fs');

const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const paired = items[i].pairedItem;
  const idx = Array.isArray(paired) ? paired[0].item : paired.item;
  const fileName = $('Parsear resultado (MT4)').all()[idx].json.fileName;
  await fs.promises.unlink(fileName);
}

return items;
